import os
import re
import pytesseract
from PIL import Image, ImageOps, ImageFilter
import pandas as pd
from datetime import datetime

def preprocess_image(image_path):
    img = Image.open(image_path)
    img = img.convert('L')
    img = ImageOps.autocontrast(img)
    img = img.filter(ImageFilter.SHARPEN)
    return img

def extract_date(text):
    # Common date patterns
    patterns = [
        r'(\d{4})[-/.](\d{2})[-/.](\d{2})',  # YYYY-MM-DD
        r'(\d{2})[-/.](\d{2})[-/.](\d{4})',  # DD-MM-YYYY or MM-DD-YYYY
        r'(\d{1,2})\s+(JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|OCT|NOV|DEC)[a-z]*\s+(\d{4})', # DD MMM YYYY
    ]

    for pattern in patterns:
        match = re.search(pattern, text, re.IGNORECASE)
        if match:
            groups = match.groups()
            if len(groups[0]) == 4: # YYYY-MM-DD
                try:
                    return datetime.strptime(f"{groups[0]}-{groups[1]}-{groups[2]}", "%Y-%m-%d").strftime("%Y-%m-%d")
                except: pass
            elif len(groups[2]) == 4: # DD-MM-YYYY or MM-DD-YYYY
                # Try DD-MM-YYYY first
                try:
                    return datetime.strptime(f"{groups[2]}-{groups[1]}-{groups[0]}", "%Y-%m-%d").strftime("%Y-%m-%d")
                except:
                    # Try MM-DD-YYYY
                    try:
                        return datetime.strptime(f"{groups[2]}-{groups[0]}-{groups[1]}", "%Y-%m-%d").strftime("%Y-%m-%d")
                    except: pass
            elif len(groups) == 3 and groups[1].isalpha(): # DD MMM YYYY
                try:
                    month_str = groups[1][:3].upper()
                    return datetime.strptime(f"{groups[2]} {month_str} {groups[0]}", "%Y %b %d").strftime("%Y-%m-%d")
                except: pass
    return None

def extract_total(text):
    lines = text.split('\n')
    keywords = [
        'GRAND TOTAL', 'TOTAL RM', 'TOTAL: RM', 'TOTAL AMOUNT',
        'TOTAL', 'AMOUNT', 'TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL'
    ]
    exclude = ['SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE', 'CASH TENDERED']

    amount_pattern = r'(\d{1,3}(?:,\d{3})*\.\d{2})'

    found_keyword_line_idx = -1
    for i, line in enumerate(lines):
        upper_line = line.upper()
        if any(ex in upper_line for ex in exclude):
            continue

        for kw in keywords:
            if kw in upper_line:
                # Try to find amount on the same line
                amounts = re.findall(amount_pattern, line)
                if amounts:
                    return f"{float(amounts[-1].replace(',', '')):*.2f}"
                found_keyword_line_idx = i
                break
        if found_keyword_line_idx != -1:
            break

    if found_keyword_line_idx != -1 and found_keyword_line_idx + 1 < len(lines):
        # Check the next line for a fallback
        next_line = lines[found_keyword_line_idx + 1]
        amounts = re.findall(amount_pattern, next_line)
        if amounts:
            return f"{float(amounts[-1].replace(',', '')):*.2f}"

    return None

# Override the extract_total with a more robust version if needed
def extract_total_robust(text):
    lines = [l.strip() for l in text.split('\n') if l.strip()]
    keywords = [
        'GRAND TOTAL', 'TOTAL RM', 'TOTAL: RM', 'TOTAL AMOUNT',
        'TOTAL', 'AMOUNT', 'TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL'
    ]
    exclude = ['SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE', 'CASH TENDERED']

    amount_pattern = r'(\d{1,3}(?:,\d{3})*\.\d{2})'

    for i, line in enumerate(lines):
        upper_line = line.upper()
        if any(ex in upper_line for ex in exclude):
            continue

        for kw in keywords:
            if kw in upper_line:
                # Look for amount on the same line
                match = re.search(amount_pattern, line)
                if match:
                    # Sometimes multiple amounts, take the last one on that line if it follows the keyword
                    matches = re.findall(amount_pattern, line[line.upper().find(kw):])
                    if matches:
                        return "{:.2f}".format(float(matches[-1].replace(',', '')))

                # Fallback to next line
                if i + 1 < len(lines):
                    next_line = lines[i+1]
                    # Make sure next line doesn't contain exclusion keywords
                    if not any(ex in next_line.upper() for ex in exclude):
                        matches = re.findall(amount_pattern, next_line)
                        if matches:
                            return "{:.2f}".format(float(matches[-1].replace(',', '')))

    return None

img_dir = 'dataset/img'
files = sorted([f for f in os.listdir(img_dir) if f.endswith('.jpg')])

results = []
for filename in files:
    path = os.path.join(img_dir, filename)
    try:
        img = preprocess_image(path)
        text = pytesseract.image_to_string(img)

        date = extract_date(text)
        total = extract_total_robust(text)

        results.append({
            'filename': filename,
            'date': date,
            'total_amount': total
        })
        print(f"Processed {filename}: {date}, {total}")
    except Exception as e:
        print(f"Error processing {filename}: {e}")
        results.append({
            'filename': filename,
            'date': None,
            'total_amount': None
        })

df = pd.DataFrame(results)
df.to_excel('stat_ocr.xlsx', sheet_name='results', index=False)

