    img = img.convert('L')
    img = ImageOps.autocontrast(img)
    img = img.filter(ImageFilter.SHARPEN)
    return img

def extract_date(text):
    # Common date patterns
    # YYYY-MM-DD, DD/MM/YYYY, MM/DD/YYYY, DD.MM.YYYY
    # Also handle single digit day/month
    patterns = [
        r'(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})',  # YYYY-MM-DD
        r'(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})',  # DD-MM-YYYY or MM-DD-YYYY
        r'(\d{1,2})\s+(JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|OCT|NOV|DEC)[a-z]*\s+(\d{4})', # DD MMM YYYY
    ]

    for pattern in patterns:
        matches = re.finditer(pattern, text, re.IGNORECASE)
        for match in matches:
            groups = match.groups()
            if len(groups[0]) == 4: # YYYY-MM-DD
                try:
                    y, m, d = int(groups[0]), int(groups[1]), int(groups[2])
                    return datetime(y, m, d).strftime("%Y-%m-%d")
                except: pass
            elif len(groups[2]) == 4: # DD-MM-YYYY or MM-DD-YYYY
                y = int(groups[2])
                # Try DD-MM-YYYY
                try:
                    d, m = int(groups[0]), int(groups[1])
                    return datetime(y, m, d).strftime("%Y-%m-%d")
                except:
                    # Try MM-DD-YYYY
                    try:
                        m, d = int(groups[0]), int(groups[1])
                        return datetime(y, m, d).strftime("%Y-%m-%d")
                    except: pass
            elif len(groups) == 3 and groups[1].isalpha(): # DD MMM YYYY
                try:
                    d = int(groups[0])
                    y = int(groups[2])
                    month_str = groups[1][:3].upper()
                    return datetime.strptime(f"{y} {month_str} {d}", "%Y %b %d").strftime("%Y-%m-%d")
                except: pass
    return None

