        'GRAND TOTAL', 'TOTAL RM', 'TOTAL: RM', 'TOTAL AMOUNT',
        'TOTAL', 'AMOUNT', 'TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL'
    ]
    exclude = ['SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE', 'CASH TENDERED']

    amount_pattern = r'(\d{1,3}(?:,\d{3})*(?:\.\d{2})?)' # Modified to handle optional .22 if needed but the task says exactly two decimal places
    amount_pattern_strict = r'(\d{1,3}(?:,\d{3})*\.\d{2})'

    for i, line in enumerate(lines):
        upper_line = line.upper()
        if any(ex in upper_line for ex in exclude):
            continue

        for kw in keywords:
            if kw in upper_line:
                # Look for amount on the same line after keyword
                kw_pos = upper_line.find(kw)
                line_after_kw = line[kw_pos + len(kw):]
                matches = re.findall(amount_pattern_strict, line_after_kw)
                if matches:
                    return "{:.2f}".format(float(matches[-1].replace(',', '')))

                # Try the whole line if not found after keyword (maybe keyword is after amount?)
                matches = re.findall(amount_pattern_strict, line)
                if matches:
                    return "{:.2f}".format(float(matches[-1].replace(',', '')))

                # Fallback to next line
                if i + 1 < len(lines):
                    next_line = lines[i+1]
                    if not any(ex in next_line.upper() for ex in exclude):
                        matches = re.findall(amount_pattern_strict, next_line)
                        if matches:
                            return "{:.2f}".format(float(matches[-1].replace(',', '')))

    return None

